{"path":"main.go","content":"package main

import (
	"bufio"
	"bytes"
	"flag"
	"fmt"
	"io"
	"net"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Database represents the key-value store
type Database struct {
	mu      sync.RWMutex
	data    map[string]*Value
	expires map[string]time.Time
}

// Value represents a stored value with optional expiry
type Value struct {
	data []byte
}

// NewDatabase creates a new database instance
func NewDatabase() *Database {
	return &Database{
		data:    make(map[string]*Value),
		expires: make(map[string]time.Time),
	}
}

// Get retrieves a value from the database, checking for expiry
func (db *Database) Get(key string) ([]byte, bool) {
	db.mu.RLock()
	defer db.mu.RUnlock()

	// Check if key exists
	val, exists := db.data[key]
	if !exists {
		return nil, false
	}

	// Check if key has expired
	if expiry, hasExpiry := db.expires[key]; hasExpiry {
		if time.Now().After(expiry) {
			// Key has expired, delete it (lazy expiry)
			db.mu.RUnlock()
			db.mu.Lock()
			delete(db.data, key)
			delete(db.expires, key)
			db.mu.Unlock()
			db.mu.RLock()
			return nil, false
		}
	}

	return val.data, true
}

// Set stores a value in the database with optional expiry
func (db *Database) Set(key string, value []byte, expiry time.Duration) {
	db.mu.Lock()
	defer db.mu.Unlock()

	db.data[key] = &Value{data: value}
	if expiry > 0 {
		db.expires[key] = time.Now().Add(expiry)
	} else {
		delete(db.expires, key)
	}
}

// Delete removes a key from the database
func (db *Database) Delete(key string) bool {
	db.mu.Lock()
	defer db.mu.Unlock()

	_, exists := db.data[key]
	if exists {
		delete(db.data, key)
		delete(db.expires, key)
		return true
	}
	return false
}

// Client represents a connected client
type Client struct {
	conn net.Conn
	db   *Database
}

// Handle processes client commands
func (c *Client) Handle() {
	defer c.conn.Close()
	reader := bufio.NewReader(c.conn)

	for {
		// Read RESP protocol command
		line, err := reader.ReadBytes('\n')
		if err != nil {
			if err != io.EOF {
				fmt.Printf("Error reading: %v\n", err)
			}
			return
		}

		// Parse RESP array
		if line[0] != '*' {
			c.replyError("ERR Protocol error: expected '*'")
			return
		}

		numArgs, err := strconv.Atoi(strings.TrimSpace(string(line[1 : len(line)-2])))
		if err != nil || numArgs < 1 {
			c.replyError("ERR Protocol error: invalid number of arguments")
			return
		}

		// Read arguments
		args := make([][]byte, 0, numArgs)
		for i := 0; i < numArgs; i++ {
			argLine, err := reader.ReadBytes('\n')
			if err != nil {
				c.replyError("ERR Protocol error: incomplete command")
				return
			}

			if argLine[0] != '$' {
				c.replyError("ERR Protocol error: expected '$'")
				return
			}

			argLen, err := strconv.Atoi(strings.TrimSpace(string(argLine[1 : len(argLine)-2])))
			if err != nil || argLen < 0 {
				c.replyError("ERR Protocol error: invalid bulk string length")
				return
			}

			arg := make([]byte, argLen)
			_, err = io.ReadFull(reader, arg)
			if err != nil {
				c.replyError("ERR Protocol error: incomplete bulk string")
				return
			}

			// Read CRLF after bulk string
			_, err = reader.ReadBytes('\n')
			if err != nil {
				c.replyError("ERR Protocol error: incomplete bulk string")
				return
			}

			args = append(args, arg)
		}

		// Execute command
		c.executeCommand(args)
	}
}

// executeCommand processes a command with its arguments
func (c *Client) executeCommand(args [][]byte) {
	if len(args) == 0 {
		c.replyError("ERR wrong number of arguments for command")
		return
	}

	cmd := strings.ToUpper(string(args[0]))

	switch cmd {
	case "PING":
		c.handlePing(args)
	case "ECHO":
		c.handleEcho(args)
	case "SET":
		c.handleSet(args)
	case "GET":
		c.handleGet(args)
	case "DEL":
		c.handleDel(args)
	default:
		c.replyError(fmt.Sprintf("ERR unknown command '%s'", cmd))
	}
}

func (c *Client) handlePing(args [][]byte) {
	if len(args) > 2 {
		c.replyError("ERR wrong number of arguments for 'ping' command")
		return
	}

	if len(args) == 1 {
		c.replySimpleString("PONG")
	} else {
		c.replyBulkString(args[1])
	}
}

func (c *Client) handleEcho(args [][]byte) {
	if len(args) != 2 {
		c.replyError("ERR wrong number of arguments for 'echo' command")
		return
	}
	c.replyBulkString(args[1])
}

func (c *Client) handleSet(args [][]byte) {
	if len(args) < 3 {
		c.replyError("ERR wrong number of arguments for 'set' command")
		return
	}

	key := string(args[1])
	value := args[2]
	var expiry time.Duration

	// Parse optional EX/PX arguments
	i := 3
	for i < len(args) {
		arg := strings.ToUpper(string(args[i]))
		if arg == "EX" || arg == "PX" {
			if i+1 >= len(args) {
				c.replyError("ERR syntax error")
				return
			}

			expiryStr := string(args[i+1])
			expiryInt, err := strconv.ParseInt(expiryStr, 10, 64)
			if err != nil || expiryInt <= 0 {
				c.replyError("ERR value is not an integer or out of range")
				return
			}

			if arg == "EX" {
				expiry = time.Duration(expiryInt) * time.Second
			} else { // PX
				expiry = time.Duration(expiryInt) * time.Millisecond
			}
			i += 2
		} else {
			// Unknown option
			c.replyError("ERR syntax error")
			return
		}
	}

	c.db.Set(key, value, expiry)
	c.replySimpleString("OK")
}

func (c *Client) handleGet(args [][]byte) {
	if len(args) != 2 {
		c.replyError("ERR wrong number of arguments for 'get' command")
		return
	}

	key := string(args[1])
	if value, ok := c.db.Get(key); ok {
		c.replyBulkString(value)
	} else {
		c.replyNull()
	}
}

func (c *Client) handleDel(args [][]byte) {
	if len(args) < 2 {
		c.replyError("ERR wrong number of arguments for 'del' command")
		return
	}

	count := 0
	for i := 1; i < len(args); i++ {
		key := string(args[i])
		if c.db.Delete(key) {
			count++
		}
	}
	c.replyInteger(int64(count))
}

// RESP protocol reply methods
func (c *Client) replySimpleString(s string) {
	c.conn.Write([]byte("+" + s + "\r\n"))
}

func (c *Client) replyError(s string) {
	c.conn.Write([]byte("-" + s + "\r\n"))
}

func (c *Client) replyInteger(n int64) {
	c.conn.Write([]byte(":" + strconv.FormatInt(n, 10) + "\r\n"))
}

func (c *Client) replyBulkString(b []byte) {
	if b == nil {
		c.replyNull()
		return
	}
	c.conn.Write([]byte("$" + strconv.Itoa(len(b)) + "\r\n"))
	c.conn.Write(b)
	c.conn.Write([]byte("\r\n"))
}

func (c *Client) replyNull() {
	c.conn.Write([]byte("$-1\r\n"))
}

func main() {
	port := flag.Int("port", 6380, "Port to listen on")
	flag.Parse()

	db := NewDatabase()
	listener, err := net.Listen("tcp", fmt.Sprintf("127.0.0.1:%d", *port))
	if err != nil {
		fmt.Printf("Failed to listen on port %d: %v\n", *port, err)
		return
	}
	defer listener.Close()

	fmt.Printf("Redis-mini server listening on 127.0.0.1:%d\n", *port)

	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Printf("Error accepting connection: %v\n", err)
			continue
		}

		client := &Client{conn: conn, db: db}
		go client.Handle()
	}
}"}

