func (w *RESP2Writer) WriteArray(elements []interface{}) error {
	_, err := fmt.Fprintf(w.writer, "*%d\r\n", len(elements))
	if err != nil {
		return err
	}

	for _, elem := range elements {
		switch v := elem.(type) {
		case string:
			err = w.WriteSimpleString(v)
		case []byte:
			err = w.WriteBulkString(v)
		case int64:
			err = w.WriteInteger(v)
		case int:
			err = w.WriteInteger(int64(v))
		case error:
			err = w.WriteError(v.Error())
		case nil:
			err = w.WriteBulkString(nil)
		default:
			err = fmt.Errorf("unsupported type: %T", v)
		}

		if err != nil {
			return err
		}
