	port := flag.Int("port", 6380, "Port to listen on")
	flag.Parse()

	db := NewDatabase()
	listener, err := net.Listen("tcp", fmt.Sprintf("127.0.0.1:%d", *port))
	if err != nil {
		fmt.Printf("Failed to listen on port %d: %v\n", *port, err)
		return
	}
