import (
	"bufio"
	"fmt"
	"net"
	"strings"
	"time"
)

func readResponse(reader *bufio.Reader) (string, error) {
	line, err := reader.ReadString('\n')
	if err != nil {
		return "", err
	}

	// For simple strings, errors, and integers, return the line
	if line[0] == '+' || line[0] == '-' || line[0] == ':' {
		return line, nil
	}

	// For bulk strings, read the length first
	if line[0] == '$' {
		response := line

		// Check if it's a null bulk string
		if strings.TrimSpace(line) == "$-1" {
			return response, nil
		}

		// Parse length
		lengthStr := strings.TrimSpace(line[1:])
		var length int
		fmt.Sscanf(lengthStr, "%d", &length)

		// Read the data
		data := make([]byte, length)
		_, err := reader.Read(data)
		if err != nil {
			return "", err
		}
		response += string(data)

		// Read the trailing CRLF
		crlf := make([]byte, 2)
		_, err = reader.Read(crlf)
		if err != nil {
			return "", err
		}
		response += string(crlf)

		return response, nil
	}

	// For arrays, we don't expect them in responses for our commands
	return line, nil
}

func sendCommand(conn net.Conn, reader *bufio.Reader, cmd string) string {
	conn.Write([]byte(cmd))
	resp, err := readResponse(reader)
	if err != nil {
		return fmt.Sprintf("ERROR: %v", err)
	}
	return resp
}

