		var length int
		fmt.Sscanf(lengthStr, "%d", &length)

		// Read the data
		data := make([]byte, length)
		_, err := reader.Read(data)
		if err != nil {
			return "", err
		}
		response += string(data)

		// Read the trailing CRLF
		crlf := make([]byte, 2)
		_, err = reader.Read(crlf)
		if err != nil {
			return "", err
		}
		response += string(crlf)

		return response, nil
	}

	// For arrays, we don't expect them in responses for our commands
	return line, nil
}

func sendCommand(conn net.Conn, reader *bufio.Reader, cmd string) string {
	conn.Write([]byte(cmd))
	resp, err := readResponse(reader)
	if err != nil {
		return fmt.Sprintf("ERROR: %v", err)
	}
	return resp
}

func testComprehensive() {
	conn, err := net.Dial("tcp", "127.0.0.1:6393")
	if err != nil {
		fmt.Printf("Failed to connect: %v\n", err)
		return
	}
	defer conn.Close()

	reader := bufio.NewReader(conn)

	// Test 1: Basic PING
	resp := sendCommand(conn, reader, "*1\r\n$4\r\nPING\r\n")
	fmt.Printf("Test 1 - PING: %q\n", resp)
	if !strings.Contains(resp, "+PONG") {
		fmt.Println("FAIL: PING didn't return PONG")
	}

	// Test 2: PING with argument
	resp = sendCommand(conn, reader, "*2\r\n$4\r\nPING\r\n$5\r\nhello\r\n")
	fmt.Printf("Test 2 - PING hello: %q\n", resp)
	if !strings.Contains(resp, "hello") {
		fmt.Println("FAIL: PING hello didn't return hello")
	}

	// Test 3: SET and GET
	resp = sendCommand(conn, reader, "*3\r\n$3\r\nSET\r\n$3\r\nfoo\r\n$3\r\nbar\r\n")
	fmt.Printf("Test 3 - SET foo bar: %q\n", resp)
	if !strings.Contains(resp, "+OK") {
		fmt.Println("FAIL: SET didn't return OK")
	}

	resp = sendCommand(conn, reader, "*2\r\n$3\r\nGET\r\n$3\r\nfoo\r\n")
	fmt.Printf("Test 4 - GET foo: %q\n", resp)
	if !strings.Contains(resp, "bar") {
		fmt.Println("FAIL: GET foo didn't return bar")
	}

	// Test 5: SET with EX
	resp = sendCommand(conn, reader, "*5\r\n$3\r\nSET\r\n$3\r\nkeyex\r\n$5\r\nvalue\r\n$2\r\nEX\r\n$1\r\n1\r\n")
	fmt.Printf("Test 5 - SET with EX 1: %q\n", resp)
	if !strings.Contains(resp, "+OK") {
		fmt.Println("FAIL: SET EX didn't return OK")
	}

	// Test 6: GET immediately (should work)
	resp = sendCommand(conn, reader, "*2\r\n$3\r\nGET\r\n$5\r\nkeyex\r\n")
	fmt.Printf("Test 6 - GET keyex (immediate): %q\n", resp)
	if !strings.Contains(resp, "value") {
		fmt.Println("FAIL: GET keyex didn't return value immediately")
	}

	// Test 7: Wait for expiry and GET (should return nil)
	fmt.Println("Waiting 2 seconds for expiry...")
	time.Sleep(2 * time.Second)
	resp = sendCommand(conn, reader, "*2\r\n$3\r\nGET\r\n$5\r\nkeyex\r\n")
	fmt.Printf("Test 7 - GET keyex (after expiry): %q\n", resp)
	if !strings.Contains(resp, "$-1") {
		fmt.Println("FAIL: GET keyex didn't return nil after expiry")
	}

	// Test 8: SET with PX
	resp = sendCommand(conn, reader, "*5\r\n$3\r\nSET\r\n$3\r\nkeypx\r\n$5\r\nvalue\r\n$2\r\nPX\r\n$3\r\n500\r\n")
	fmt.Printf("Test 8 - SET with PX 500: %q\n", resp)
	if !strings.Contains(resp, "+OK") {
		fmt.Println("FAIL: SET PX didn't return OK")
	}

	// Test 9: GET immediately (should work)
	resp = sendCommand(conn, reader, "*2\r\n$3\r\nGET\r\n$5\r\nkeypx\r\n")
	fmt.Printf("Test 9 - GET keypx (immediate): %q\n", resp)
	if !strings.Contains(resp, "value") {
		fmt.Println("FAIL: GET keypx didn't return value immediately")
	}

	// Test 10: Wait for PX expiry and GET (should return nil)
	fmt.Println("Waiting 1 second for PX expiry...")
	time.Sleep(1 * time.Second)
	resp = sendCommand(conn, reader, "*2\r\n$3\r\nGET\r\n$5\r\nkeypx\r\n")
	fmt.Printf("Test 10 - GET keypx (after expiry): %q\n", resp)
	if !strings.Contains(resp, "$-1") {
		fmt.Println("FAIL: GET keypx didn't return nil after PX expiry")
	}

	// Test 11: DEL multiple keys
	resp = sendCommand(conn, reader, "*3\r\n$3\r\nSET\r\n$4\r\nkey1\r\n$6\r\nvalue1\r\n")
	fmt.Printf("Test 11 - SET key1: %q\n", resp)

	resp = sendCommand(conn, reader, "*3\r\n$3\r\nSET\r\n$4\r\nkey2\r\n$6\r\nvalue2\r\n")
	fmt.Printf("Test 12 - SET key2: %q\n", resp)

	resp = sendCommand(conn, reader, "*4\r\n$3\r\nDEL\r\n$4\r\nkey1\r\n$4\r\nkey2\r\n$4\r\nkey3\r\n")
	fmt.Printf("Test 13 - DEL key1 key2 key3: %q\n", resp)
	if !strings.Contains(resp, ":2") {
		fmt.Println("FAIL: DEL should return :2 (deleted 2 keys)")
	}

	// Test 14: Wrong arity
	resp = sendCommand(conn, reader, "*1\r\n$3\r\nGET\r\n")
	fmt.Printf("Test 14 - Wrong arity GET: %q\n", resp)
	if !strings.Contains(resp, "-ERR wrong number of arguments") {
		fmt.Println("FAIL: Wrong arity should return error")
	}

	// Test 15: Unknown command
	resp = sendCommand(conn, reader, "*1\r\n$6\r\nFOOBAR\r\n")
	fmt.Printf("Test 15 - Unknown command: %q\n", resp)
	if !strings.Contains(resp, "-ERR unknown command") {
		fmt.Println("FAIL: Unknown command should return error")
	}

	// Test 16: ECHO
	resp = sendCommand(conn, reader, "*2\r\n$4\r\nECHO\r\n$11\r\nhello world\r\n")
	fmt.Printf("Test 16 - ECHO hello world: %q\n", resp)
	if !strings.Contains(resp, "hello world") {
		fmt.Println("FAIL: ECHO didn't return hello world")
	}

	// Test 17: SET with invalid EX value
	resp = sendCommand(conn, reader, "*5\r\n$3\r\nSET\r\n$3\r\nkey\r\n$5\r\nvalue\r\n$2\r\nEX\r\n$3\r\nabc\r\n")
	fmt.Printf("Test 17 - SET with invalid EX: %q\n", resp)
	if !strings.Contains(resp, "-ERR value is not an integer") {
		fmt.Println("FAIL: Invalid EX should return error")
	}

	// Test 18: SET with negative EX value
	resp = sendCommand(conn, reader, "*5\r\n$3\r\nSET\r\n$3\r\nkey\r\n$5\r\nvalue\r\n$2\r\nEX\r\n$2\r\n-1\r\n")
	fmt.Printf("Test 18 - SET with negative EX: %q\n", resp)
	if !strings.Contains(resp, "-ERR value is not an integer") {
		fmt.Println("FAIL: Negative EX should return error")
	}

	// Test 19: SET with 0 EX value
	resp = sendCommand(conn, reader, "*5\r\n$3\r\nSET\r\n$3\r\nkey\r\n$5\r\nvalue\r\n$2\r\nEX\r\n$1\r\n0\r\n")
	fmt.Printf("Test 19 - SET with 0 EX: %q\n", resp)
	if !strings.Contains(resp, "-ERR value is not an integer") {
		fmt.Println("FAIL: Zero EX should return error")
	}

	fmt.Println("\nAll tests completed!")
}

func main() {
	testComprehensive()
}"}

