func readFullResponse(reader *bufio.Reader) (string, error) {
	var response strings.Builder

	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return response.String(), err
		}
		response.WriteString(line)

		// Check if we have a complete response
		// For simple string, error, integer: just the line
		if len(line) >= 2 && line[0] == '+' || line[0] == '-' || line[0] == ':' {
			if strings.HasSuffix(line, "\r\n") {
				return response.String(), nil
			}
		}

		// For bulk string: check if we've read the data
		if len(line) >= 2 && line[0] == '$' {
			// Parse length
			lengthStr := strings.TrimSpace(line[1:])
			if lengthStr == "-1" {
				return response.String(), nil
			}

			var length int
			fmt.Sscanf(lengthStr, "%d", &length)

			// Read the data
			data := make([]byte, length)
			_, err := reader.Read(data)
			if err != nil {
				return response.String(), err
			}
			response.Write(data)

			// Read the trailing CRLF
			crlf := make([]byte, 2)
			_, err = reader.Read(crlf)
			if err != nil {
				return response.String(), err
			}
			response.Write(crlf)

			return response.String(), nil
		}
	}
}

