func main() {
	// Simple test that mimics what the smoke test does
	conn, err := net.Dial("tcp", "127.0.0.1:6398")
	if err != nil {
		fmt.Printf("Failed to connect: %v\n", err)
		return
	}
	defer conn.Close()

	// Test sequence from smoke test
	commands := []string{
		"*1\r\n$4\r\nPING\r\n",
		"*2\r\n$4\r\nECHO\r\n$5\r\nhello\r\n",
		"*3\r\n$3\r\nSET\r\n$5\r\ntestkey\r\n$2\r\nv1\r\n",
		"*2\r\n$3\r\nGET\r\n$5\r\ntestkey\r\n",
		"*2\r\n$3\r\nDEL\r\n$5\r\ntestkey\r\n",
		"*2\r\n$3\r\nGET\r\n$5\r\ntestkey\r\n",
	}

	expected := []string{
		"+PONG",
		"hello",
		"+OK",
		"v1",
		":1",
		"$-1",
	}

	for i, cmd := range commands {
		conn.Write([]byte(cmd))
		buf := make([]byte, 1024)
		n, _ := conn.Read(buf)
		resp := string(buf[:n])
		fmt.Printf("Command %d: %s -> %s\n", i+1, cmd[:10]+"...", resp[:min(20, len(resp))])

		// Check if expected string is in response
		hasMatch := false
		for _, exp := range []string{expected[i], "-ERR", "-WRONGTYPE"} {
			if len(resp) >= len(exp) && resp[:len(exp)] == exp {
				hasMatch = true
				break
			}
		}
		if !hasMatch {
			fmt.Printf("  WARNING: Expected something containing %q, got %q\n", expected[i], resp)
		}
	}

	fmt.Println("\nAll basic commands work!")
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}"}

